<template><view v-if="organizations.length" class="owner-group"><text class="owner-heading">负责人管理</text><button v-for="org in organizations" :key="org.id" class="owner-row" :disabled="busy" @tap="transfer(org)"><view class="owner-icon"><PrototypeIcon name="shield" :size="34"/></view><view><text>{{org.name}}</text><text class="owner-caption">转交负责人</text></view><PrototypeIcon name="arrow" tone="muted" :size="24"/></button><text v-if="error" class="owner-error">{{error}}</text></view></template>
<script setup lang="ts">
import PrototypeIcon from '@/components/PrototypeIcon.vue';
import {ref,watch,onMounted} from 'vue';
import {onShow,onHide,onUnload} from '@dcloudio/uni-app';
import {request} from '@/api/http';
import {onboardingApi,type MyOrganization} from '@/api/organization-onboarding';
import {resolveOnboardingSession,type OnboardingIdentity} from '@/session/onboarding-session';
const props=defineProps<{identity:OnboardingIdentity;organizationId?:string}>(),organizations=ref<MyOrganization[]>([]),busy=ref(false),error=ref('');
let viewEpoch=0,loadEpoch=0;function hide(){viewEpoch++;loadEpoch++;organizations.value=[];busy.value=false;}onHide(hide);onUnload(hide);onShow(()=>{viewEpoch++;void load();});
watch(()=>props.organizationId,()=>{viewEpoch++;loadEpoch++;organizations.value=[];busy.value=false;void load();});
// 晚挂载兜底：宿主页面在 onShow 中异步赋值 organizationId 后本组件才挂载时，会错过本次 onShow 且 watch 不触发，mounted 时直接加载一次。
onMounted(()=>{void load();});
async function load(){const l=viewEpoch,n=++loadEpoch;organizations.value=[];const session=await resolveOnboardingSession(props.identity);if(!session||l!==viewEpoch||n!==loadEpoch)return;try{const requestedOrganization=props.organizationId;const rows=await onboardingApi.organizations(session.accessToken);const fresh=await resolveOnboardingSession(props.identity);if(l!==viewEpoch||n!==loadEpoch||fresh?.accessToken!==session.accessToken||requestedOrganization!==props.organizationId)return;for(const org of rows.filter(x=>x.owner&&(!requestedOrganization||x.id===requestedOrganization))){try{await request(`/organization-onboarding/organizations/${org.id}/owner-transfer-options`,{header:{Authorization:`Bearer ${session.accessToken}`}});const fresh=await resolveOnboardingSession(props.identity);if(l===viewEpoch&&n===loadEpoch&&fresh?.accessToken===session.accessToken)organizations.value.push(org);}catch{ /* Server permission and actual owner checks determine availability. */ }}}catch{}}
async function transfer(org:MyOrganization){const l=viewEpoch;const session=await resolveOnboardingSession(props.identity);if(!session||busy.value||l!==viewEpoch||(props.organizationId&&org.id!==props.organizationId))return;busy.value=true;error.value='';try{const options=await request<{id:string;name:string}[]>(`/organization-onboarding/organizations/${org.id}/owner-transfer-options`,{header:{Authorization:`Bearer ${session.accessToken}`}});const context=await onboardingApi.context(session.accessToken);if(l!==viewEpoch)return;const targets=options.filter(x=>x.id!==context.userId);if(!targets.length)throw new Error('请先添加其他有效管理员');const chosen=await uni.showActionSheet({itemList:targets.map(x=>x.name)});const target=targets[chosen.tapIndex];if(!target||l!==viewEpoch)return;const confirmation=await uni.showModal({title:'转交负责人',content:`将 ${org.name} 的负责人转交给 ${target.name}？`});if(!confirmation.confirm||l!==viewEpoch)return;const current=await resolveOnboardingSession(props.identity);if(current?.accessToken!==session.accessToken||l!==viewEpoch)return;await request(`/organization-onboarding/organizations/${org.id}/owner-transfer`,{method:'POST',data:{targetUserId:target.id},header:{Authorization:`Bearer ${session.accessToken}`}});const after=await resolveOnboardingSession(props.identity);if(l!==viewEpoch||after?.accessToken!==session.accessToken)return;await load();if(l!==viewEpoch)return;uni.showToast({title:'已转交',icon:'success'});}catch(e){if(l!==viewEpoch)return;error.value=e instanceof Error?e.message:'转交未完成';}finally{if(l===viewEpoch)busy.value=false;}}
</script>

<style scoped>.owner-group{background:#fffefa;border:1rpx solid #e6edde;border-radius:24rpx;overflow:hidden;margin:22rpx 0;}.owner-heading{display:block;font-size:23rpx;color:#82937c;margin:24rpx 24rpx 2rpx;}.owner-row{display:flex;align-items:center;gap:18rpx;width:100%;padding:20rpx 24rpx;margin:0;background:transparent;text-align:left;color:#385b40;font-size:27rpx;line-height:1.5;}.owner-row::after{border:0;}.owner-icon{padding:10rpx;border-radius:14rpx;background:#edf3e8;}.owner-row>view:nth-child(2){flex:1;min-width:0;}.owner-row>view>text{display:block;}.owner-caption{font-size:22rpx;color:#8a9880;margin-top:5rpx;}.owner-error{display:block;font-size:24rpx;color:#b06c51;padding:20rpx;}</style>